import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.C9_66ieh.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1785285564000}'),a={name:"architecture.md"};function s(c,e,n,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>TrueDeck is a desktop app: <strong>Electron main</strong> owns processes and data, <strong>preload</strong> exposes a typed IPC API, and the <strong>renderer</strong> is a React + xterm Studio UI. The <strong>Rust</strong> <code>truedeck-backend</code> is the main session engine.</p><h2 id="high-level-stack" tabindex="-1">High-level stack <a class="header-anchor" href="#high-level-stack" aria-label="Permalink to &quot;High-level stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>What runs there</th></tr></thead><tbody><tr><td><strong>Renderer</strong> (<code>src/</code>)</td><td>React, zustand store, xterm panes, TaskBoard, Settings</td></tr><tr><td><strong>IPC</strong></td><td><code>contextBridge</code> / preload (<code>window.truedeck</code>)</td></tr><tr><td><strong>Electron main</strong> (<code>electron/main/</code>)</td><td>App lifecycle, pty-manager, tasks, mcp-hub, memory, agents, session layout</td></tr><tr><td><strong>Session engine</strong></td><td><strong>Rust <code>truedeck-backend</code></strong> (primary); <code>node-pty</code> only if Rust cannot start</td></tr><tr><td><strong>Agents</strong></td><td>Real CLIs in ConPTY / PTY under the project root</td></tr></tbody></table><h2 id="process-roles" tabindex="-1">Process roles <a class="header-anchor" href="#process-roles" aria-label="Permalink to &quot;Process roles&quot;">​</a></h2><h3 id="main-electron-main" tabindex="-1">Main (<code>electron/main/</code>) <a class="header-anchor" href="#main-electron-main" aria-label="Permalink to &quot;Main (`electron/main/`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>index.ts</code></td><td>App lifecycle, BrowserWindow, settings IPC, session restore orchestration</td></tr><tr><td><code>pty-manager.ts</code></td><td>Session map, spawn/write/resize/kill, rust vs node-pty backend</td></tr><tr><td><code>resolve-command.ts</code></td><td>PATH / known-path CLI resolve; <strong>blocks Cursor IDE</strong></td></tr><tr><td><code>agents.ts</code></td><td>Default agent presets + <code>agents.json</code> merge</td></tr><tr><td><code>session-layout.ts</code></td><td>Persist/load pane tree; max 16 tabs</td></tr><tr><td><code>tasks.ts</code> / <code>task-dispatch.ts</code> / <code>runs.ts</code></td><td>Kanban store, dispatch to PTY, run records</td></tr><tr><td><code>mcp-hub.ts</code></td><td>Unified MCP config write/sync to agent clients</td></tr><tr><td><code>memory-service.ts</code> / <code>memory-providers.ts</code> / <code>mempalace.ts</code></td><td>Auto-context, env inject, providers</td></tr><tr><td><code>agent-frame.ts</code></td><td>Wrap spawn in <code>truedeck-frame.mjs</code> when enabled</td></tr><tr><td><code>backend-bridge.ts</code></td><td>JSON-RPC stdio to <code>truedeck-backend</code></td></tr><tr><td><code>rust-pty-host.ts</code></td><td>JSON-lines host for <code>truedeck-pty</code></td></tr><tr><td><code>paths.ts</code></td><td>App data and memory directory helpers</td></tr><tr><td><code>projects.ts</code></td><td>Project list CRUD</td></tr><tr><td><code>first-run.ts</code> / <code>onboarding.ts</code></td><td>First-run / onboarding flow</td></tr></tbody></table><h3 id="preload-electron-preload-index-ts" tabindex="-1">Preload (<code>electron/preload/index.ts</code>) <a class="header-anchor" href="#preload-electron-preload-index-ts" aria-label="Permalink to &quot;Preload (`electron/preload/index.ts`)&quot;">​</a></h3><p>Exposes <code>window.truedeck</code> methods (<code>spawn</code>, settings, MCP, tasks, restore, …) via <code>contextBridge</code>. Renderer never gets raw Node APIs.</p><h3 id="renderer-src" tabindex="-1">Renderer (<code>src/</code>) <a class="header-anchor" href="#renderer-src" aria-label="Permalink to &quot;Renderer (`src/`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Area</th><th>Role</th></tr></thead><tbody><tr><td><code>App.tsx</code></td><td>Shortcuts, project/session lifecycle, palette, board/settings chrome</td></tr><tr><td><code>components/TerminalPane.tsx</code></td><td>xterm instance, fit, write IPC, shortcut filter</td></tr><tr><td><code>components/PaneWorkspace.tsx</code> / <code>lib/pane-layout.ts</code></td><td>Nested split tree, drag targets, max panes</td></tr><tr><td><code>components/TaskBoard.tsx</code></td><td>Kanban UI</td></tr><tr><td><code>components/SettingsMenu.tsx</code></td><td>Settings tabs</td></tr><tr><td><code>store.ts</code></td><td>Lightweight client state (zustand)</td></tr></tbody></table><h3 id="shared-types-electron-shared-types-ts" tabindex="-1">Shared types (<code>electron/shared/types.ts</code>) <a class="header-anchor" href="#shared-types-electron-shared-types-ts" aria-label="Permalink to &quot;Shared types (`electron/shared/types.ts`)&quot;">​</a></h3><p>Single source for <code>AgentPreset</code>, <code>AppSettings</code>, <code>SessionInfo</code>, <code>SessionLayout</code>, <code>Task</code>, <code>MemoryProviderConfig</code>, etc.</p><h2 id="pty-backends" tabindex="-1">PTY backends <a class="header-anchor" href="#pty-backends" aria-label="Permalink to &quot;PTY backends&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Priority</th><th>Backend</th><th>Build</th><th>Docs</th></tr></thead><tbody><tr><td><strong>1 (primary)</strong></td><td><strong>truedeck-backend</strong></td><td><code>npm run build:backend</code></td><td><a href="./RUST-BACKEND">RUST-BACKEND.md</a></td></tr><tr><td>2</td><td>truedeck-pty</td><td><code>npm run build:pty</code></td><td><a href="./FAST-PTY">FAST-PTY.md</a></td></tr><tr><td>3 (last resort)</td><td>node-pty</td><td>npm postinstall</td><td>Built-in native module</td></tr></tbody></table><p>Env overrides:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th></tr></thead><tbody><tr><td><code>TRUEDECK_BACKEND_BIN</code></td><td>Path to <code>truedeck-backend</code> executable</td></tr><tr><td><code>TRUEDECK_PTY_BIN</code></td><td>Path to <code>truedeck-pty</code> executable</td></tr><tr><td><code>TRUEDECK_DATA_DIR</code></td><td>Override app data directory (also used by hub MCP)</td></tr></tbody></table><p>Every session gets terminal identity env: <code>TERM=xterm-256color</code>, <code>COLORTERM=truecolor</code>, <code>TERM_PROGRAM=TrueDeck</code>.</p><h2 id="pane-layout" tabindex="-1">Pane layout <a class="header-anchor" href="#pane-layout" aria-label="Permalink to &quot;Pane layout&quot;">​</a></h2><p>Runtime layout is a tree of <strong>leaves</strong> (groups with tab lists) and <strong>splits</strong> (<code>row</code> | <code>column</code> + ratio).</p><p>Persisted form (<code>SessionLayout</code>):</p><ul><li><code>version: 2</code> with <code>paneTree</code> when multi-pane is used</li><li><code>tabs[]</code> as agent/command snapshots (not live PTY ids)</li><li>Indices map tree leaves back to restored session order</li></ul><p>Helpers live in <code>src/lib/pane-layout.ts</code> (renderer) and <code>electron/main/session-layout.ts</code> (disk clamp/sanitize).</p><h2 id="session-restore" tabindex="-1">Session restore <a class="header-anchor" href="#session-restore" aria-label="Permalink to &quot;Session restore&quot;">​</a></h2><ol><li>Renderer loads settings; if <code>reopenLastProject</code>, call <code>sessions:restore</code></li><li>Main loads <code>session-layout.json</code>, clamps tabs (max 16), filters install helpers</li><li>For each tab, resolve agent + spawn PTY (memory env, agent frame when enabled)</li><li>Renderer rebuilds pane tree from saved structure + new session ids</li></ol><h2 id="memory-inject" tabindex="-1">Memory inject <a class="header-anchor" href="#memory-inject" aria-label="Permalink to &quot;Memory inject&quot;">​</a></h2><table tabindex="0"><thead><tr><th>When</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Project open</strong></td><td>Ensure <code>.memory/</code>, warm MemPalace, write <code>auto-context.md</code></td></tr><tr><td><strong>Agent spawn</strong></td><td><code>onAgentSpawnFast</code> sets <code>TRUEDECK_*</code> env and MCP pointers as configured</td></tr></tbody></table><p>See <a href="./memory-providers">memory-providers.md</a>. Env bag includes <code>TRUEDECK_PROJECT</code>, <code>TRUEDECK_REPO_MEMORY</code>, <code>TRUEDECK_PALACE</code>, <code>TRUEDECK_AUTO_CONTEXT</code>, and related keys.</p><h2 id="agent-frame-wrap" tabindex="-1">Agent frame wrap <a class="header-anchor" href="#agent-frame-wrap" aria-label="Permalink to &quot;Agent frame wrap&quot;">​</a></h2><p>If <code>agentFrameTui</code> is enabled (default true), <code>pty-manager</code> wraps the CLI with:</p><p><code>node truedeck-frame.mjs --agent &lt;id&gt; --name … --cwd &lt;root&gt; -- &lt;resolved CLI&gt; …</code></p><p>Shell / <code>cmd-*</code> panes only wrap when <code>frameShellPanes</code> is true. See <a href="./agent-frame">Agent frame</a>.</p><h2 id="mcp-hub" tabindex="-1">MCP hub <a class="header-anchor" href="#mcp-hub" aria-label="Permalink to &quot;MCP hub&quot;">​</a></h2><p><code>mcp-hub.ts</code> merges:</p><ol><li>Built-in <strong>truedeck-hub</strong> (<code>resources/mcp-server/truedeck-mcp.mjs</code>)</li><li>Memory-provider MCP servers</li><li>User servers in <code>mcp-servers.json</code></li></ol><p>Then injects the same stdio set into Cursor / Claude Code / Grok / Codex / Gemini configs and project <code>.mcp.json</code>. See <a href="./mcp">MCP</a>.</p><h2 id="task-dispatch" tabindex="-1">Task dispatch <a class="header-anchor" href="#task-dispatch" aria-label="Permalink to &quot;Task dispatch&quot;">​</a></h2><p><code>task-dispatch.ts</code>:</p><ol><li>Write <code>.truedeck/tasks/&lt;shortId&gt;.md</code> + <code>.truedeck/current-focus.md</code></li><li>Spawn agent with <code>TRUEDECK_TASK*</code> env</li><li>Start a run record; mark task <code>running</code></li><li>Best-effort seed prompt into PTY after ~1.2s</li><li>On session exit → task moves toward <code>review</code> (or blocked on failure)</li></ol><h2 id="tui-mode" tabindex="-1">TUI mode <a class="header-anchor" href="#tui-mode" aria-label="Permalink to &quot;TUI mode&quot;">​</a></h2><p><code>tui/</code> is a separate entry (<code>npm run tui</code>) that reuses agent resolve / sessions concepts without Electron’s renderer. Packaging and most docs focus on Studio.</p><h2 id="packaging" tabindex="-1">Packaging <a class="header-anchor" href="#packaging" aria-label="Permalink to &quot;Packaging&quot;">​</a></h2><p><code>electron-builder</code> packs <code>out/**/*</code> plus <code>extraResources</code>:</p><ul><li><code>resources/bin</code> (Rust binaries if present)</li><li><code>resources/mcp-server</code></li><li><code>resources/agent-frame</code></li><li>icons</li></ul><p>See <a href="./development">Development</a>.</p><h2 id="related-deep-dives" tabindex="-1">Related deep dives <a class="header-anchor" href="#related-deep-dives" aria-label="Permalink to &quot;Related deep dives&quot;">​</a></h2><ul><li><a href="./FAST-PTY">Fast PTY</a> - PTY-only Rust sidecar</li><li><a href="./RUST-BACKEND">Rust backend</a> - full native service protocol</li><li><a href="./agents">Agents</a> - resolve and spawn policy</li></ul>',47)])])}const m=t(a,[["render",s]]);export{u as __pageData,m as default};
